var a=[{title:`Wiele przyczyn, wiele reakcji`,text:`Ludzie odczuwają dyskomfort w plecach z różnych powodów, a nawet podobne objawy mogą mieć różne przyczyny. Niektórzy dobrze tolerują pochylanie się, a inni wolą bardziej neutralny tułów. Najlepsze ćwiczenie dla Ciebie zależy od objawów, możliwości, doświadczenia i wszelkich porad Twojego lekarza lub terapeuty.`},{title:`Zarządzanie obciążeniami`,text:`Ćwicz usztywnianie bez zbyt długiego wstrzymywania oddechu, naucz się kontrolowanego zawiasu z lekkim ciężarem i próbuj ćwiczeń z podparciem lub na podłodze, gdy Ci odpowiadają. Delikatny ptak-pies (bird dog) lub martwy robak trenuje kontrolę tułowia bez ciężkich obciążeń. Żadna pojedyncza postawa nie gwarantuje bezpieczeństwa, a utrzymywanie „neutralnego kręgosłupa” nie oznacza zamrażania każdego normalnego ruchu kręgosłupa.`},{title:`Postęp z czasem`,text:`Jeśli jest to wygodne, stopniowo utrudniaj trening, dodając powtórzenia, zakres lub obciążenie. Zapisuj, jak czują się Twoje plecy podczas treningów i po nich. Jeśli objawy się nasilają, ułatw ćwiczenia. Przy utrzymującym się bólu zasięgnij porady specjalisty; wybór ćwiczeń przez aplikację jej nie zastąpi.`},{title:`Pilne sygnały`,text:`Nowe zmiany dotyczące pęcherza lub jelit, drętwienie w okolicy pachwiny, silne lub narastające osłabienie nogi albo ból pleców po poważnym urazie wymagają pilnej oceny medycznej.`},{title:`Korzystanie z TrainUp`,text:`Dodaj dolny odcinek pleców jako ograniczenie w Profilu, z notatką, aby plan wybierał pasujące ćwiczenia. Po każdym treningu możesz dodać notatki i zgłosić ból wraz z częścią ciała i ćwiczeniem. Jeśli ćwiczenie wywołuje ból, „Czuję ból” kończy je i trzyma poza Twoimi planami, dopóki nie wznowisz go w Profilu. TrainUp nie diagnozuje przyczyny bólu pleców.`}];var o=[{label:`NHS: ból pleców i pilne sygnały ostrzegawcze`,url:`https://www.nhs.uk/conditions/back-pain/`},{label:`Stanowisko ACSM z 2026 roku`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var n={sections:a,sources:o};export{n as default,a as sections,o as sources};